/*updateSellerMpIvDeliveryDateReg*/
UPDATE ICOMPODT_MNG
SET 
	  CONFIRM_FLAG = 'Y'
	  , CONFIRM_ID = #{confriom_user_id}
	  , CONFIRM_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
	  , CONFIRM_TIME =  TO_CHAR(SYSDATE, 'HH24MISS')         
WHERE
		BUYER	= #{buyer}
	AND PO_NO	= #{po_no}
	AND PO_SEQ	= #{po_seq}
	AND REVISION = #{revision}
